// Build Internal Error Message
// Part of: [Shared] Sub: Handle process error
// Returns: compact JSON string conforming to the internal error contract
//
// Trigger parameters (#trigger.data.*) are passed by the calling
// inline by the Frends runtime.
// ---------------------------------------------------------------

// 1. Resolve all trigger parameters and environment references
//    into local variables. This keeps the JObject construction
//    below clean C# with no mixed-syntax expressions.
var error            = #trigger.data.error;
var topLevelProcessName = #trigger.data.topLevelProcessName;
var topLevelProcessExecutionId = #trigger.data.topLevelProcessExecutionId;
var tenantBaseUrl    = #env.FRENDS_PLATFORM.tenantBaseUrl;
var customer         = #trigger.data.customer;

// 2. Extract error details safely.
//    var.error is a .NET Exception; it is passed from the calling
//    process as #trigger.data.error. Verify property names via
//    IntelliSense if your Frends version wraps the exception differently.
var errorMessage    = "Unknown error";
var errorType       = "Unknown";
var stackTrace      = string.Empty;
string innerMessage = null;

try
{
    if (error != null)
    {
        errorMessage = error.Message            ?? "Unknown error";
        errorType    = error.GetType().FullName  ?? "Unknown";
        stackTrace   = error.StackTrace          ?? string.Empty;
        innerMessage = error.InnerException?.Message;
    }
}
catch
{
    // Fallback if the error object is a non-standard wrapper
    errorMessage = error?.ToString() ?? "Unknown error";
}

// 3. Build the direct link to the Process Instance log.
var instanceUrl = !string.IsNullOrWhiteSpace(tenantBaseUrl) && !string.IsNullOrWhiteSpace(topLevelProcessExecutionId)
    ? $"{tenantBaseUrl.TrimEnd('/')}/ProcessInstance/Instance/{topLevelProcessExecutionId}"
    : null;

// 5. Build the error message object.
var message = new JObject
{
    // Envelope
    ["schemaVersion"] = "1.0",
    ["messageId"]     = Guid.NewGuid().ToString(),
    ["timestamp"]     = DateTime.UtcNow.ToString("o"),
    ["source"]        = "Frends",

    // Tenant / routing context
    ["customer"]      = customer,

    // Frends process context — process references resolved inline
    ["process"] = new JObject
    {
        ["name"]        = topLevelProcessName,
        ["executionId"] = topLevelProcessExecutionId,
        ["instanceUrl"] = instanceUrl
    },

    // Error detail
    ["error"] = new JObject
    {
        ["message"]      = errorMessage,
        ["type"]         = errorType,
        ["stackTrace"]   = stackTrace,
        ["innerMessage"] = innerMessage
    },

    // Do not put payloads or secrets here; use instanceUrl to access logs
    ["payloadRef"] = "See instanceUrl for logged input and output"
};

// 6. Return compact JSON — the queue send task uses this as the message body.
return message;"},"shouldAssignVariable":{"mode":"toggle","value":true},"variableName":"errorEvent"},"SelectedTypeId":null,"PromoteResultAs":null,"Name":"Create Error Event JSON","Description":null,"IsDefault":null,"ShouldRetry":null,"MaxRetryCount":null,"ShouldNotLogResult":null,"ShouldDispose":null},{"Id":"Event_0v0jvwz","Type":5,"Parameters":{"expression":{"mode":"text","value":"{{#var.errorEvent}}"}},"SelectedTypeId":null,"PromoteResultAs":null,"Name":null,"Description":null,"IsDefault":null,"ShouldRetry":null,"MaxRetryCount":null,"ShouldNotLogResult":null,"ShouldDispose":null},{"Id":"Activity_0lwducw","Type":1,"Parameters":{"input":{"ChannelId":{"mode":"text","value":"{{#env.SLACK_CONNECTION.channelId}}"},"Mode":{"mode":"select","value":"Blocks"},"Text":{"mode":"text","value":""},"Blocks":{"mode":"text","value":"{{#var.slackMessage}}"},"ThreadTs":{"mode":"text","value":""}},"connection":{"Token":{"mode":"text","value":"{{#env.SLACK_CONNECTION.token}}"}},"options":{"UnfurlLinks":{"mode":"toggle","value":true},"UnfurlMedia":{"mode":"toggle","value":true},"ThrowErrorOnFailure":{"mode":"toggle","value":true},"ErrorMessageOnFailure":{"mode":"text","value":"Failed to send message to Slack"}},"cancellationToken":null},"SelectedTypeId":"/ProcessTask/8df5d07c-6c35-417c-b6c9-f0ce0721b9cd/v1","PromoteResultAs":null,"Name":"Slack SendMessage","Description":null,"IsDefault":null,"ShouldRetry":false,"MaxRetryCount":null,"ShouldNotLogResult":null,"ShouldDispose":null},{"Id":"Activity_0naihmj","Type":12,"Parameters":{"useStatementMode":{"mode":"toggle","value":true},"variableExpression":{"mode":"csharp","value":"// Reads the error JObject produced by the Build Internal Error Message task.
