var processName  = (string)err["process"]["name"];
var instanceUrl  = (string)err["process"]["instanceUrl"];   // once added per above
var timestamp    = (string)err["timestamp"];
var errorMessage = (string)err["error"]["message"];
var errorType    = (string)err["error"]["type"];
var environment  = #process.environment;   // same env for sub and parent

var errorText = errorMessage.Length > 2800
    ? errorMessage.Substring(0, 2800) + " ...(truncated)"
    : errorMessage;

var fields = new JArray
{
    new JObject { ["type"] = "mrkdwn", ["text"] = $"*Customer:*\n{customer}" },
    new JObject { ["type"] = "mrkdwn", ["text"] = $"*Process:*\n{processName}" },
    new JObject { ["type"] = "mrkdwn", ["text"] = $"*Time (UTC):*\n{timestamp}" },
    new JObject { ["type"] = "mrkdwn", ["text"] = $"*Type:*\n`{errorType}`" }
};

var blocks = new JArray
{
    new JObject
    {
        ["type"] = "header",
        ["text"] = new JObject
        {
            ["type"]  = "plain_text",
            ["text"]  = ":rotating_light: Integration error",
            ["emoji"] = true
        }
    },
    new JObject { ["type"] = "divider" },
    new JObject { ["type"] = "section", ["fields"] = fields },
    new JObject { ["type"] = "divider" },
    new JObject
    {
        ["type"] = "section",
        ["text"] = new JObject { ["type"] = "mrkdwn", ["text"] = $"*Error message:*\n```{errorText}```" }
    },
    new JObject { ["type"] = "divider" }
};

// Only add the button if we actually have a link. A button with a
// null/empty url is rejected by Slack and fails the whole message.
if (!string.IsNullOrWhiteSpace(instanceUrl))
{
    blocks.Add(new JObject
    {
        ["type"]     = "actions",
        ["elements"] = new JArray
        {
            new JObject
            {
                ["type"]  = "button",
                ["text"]  = new JObject { ["type"] = "plain_text", ["text"] = ":mag: Open in Frends", ["emoji"] = true },
                ["url"]   = instanceUrl,
                ["style"] = "primary"
            }
        }
    });
}

